"""Curated phrase dictionaries for extension localization."""

from __future__ import annotations

from typing import Dict

# Technical keywords that stay identical in every locale. Adding a string here
# auto-generates a passthrough ("X" → "X") in every TRANSLATIONS locale, so the
# coverage gate counts it as translated without duplicating the entry 19+ times.
# Only add strings whose English source value is a technical identifier, column
# header keyword, or code-level token — never ordinary user-facing prose.
# WARNING: a DO_NOT_TRANSLATE entry silently suppresses translation for EVERY
# locale. Before adding a common word like "Web" or "Mobile", verify it only
# appears as a standalone source string and is genuinely untranslatable in all
# 24 locales. generate_locales.py runs _check_dnt_collisions() to catch cases
# where the keyword is embedded in a longer translatable string.
DO_NOT_TRANSLATE: list[str] = [
    "Migration",
    "Mobile",
    "Web",
    "runtime_tier",
    "rule_name",
    "saropa_quality_gate.yaml thresholds",
    "saropa_tier",
    "{grade} · {score}/100",
    # Product/SDK proper nouns and the Saropa feature name — one spelling worldwide.
    "Dart SDK",
    "Flutter SDK",
    "Flutter daemons",
    "Vibrancy",
    # Dart analyzer comment directive — literal code syntax, never translated.
    "// ignore_for_file:",
    # Version-source labels: "saropa_lints" and "pubspec"/"plugin route" are
    # config-file / package identifiers, not prose. setdefault keeps any locale
    # that already carries a curated translation.
    "saropa_lints: pubspec {version}",
    "saropa_lints: pubspec + plugin {version}",
    "saropa_lints: plugin route {version}",
    # Memory readout: RSS and heap are process-metric terms, universally English.
    "{rss} RSS · {heap} / {heapTotal} heap",
    # Product/protocol names and abbreviations written the same worldwide.
    "WASM",
    "GitHub Actions CI",
    "+docs",
    "N/A",
    "UPDATE",
]

# Words that are spelled identically in specific locales (cognates, loanwords,
# shared technical terms). Unlike DO_NOT_TRANSLATE, these apply only to the
# listed locales — the same word might need a real translation elsewhere.
# Format: English source string → list of locale codes where it is correct as-is.
# The merge loop below injects "X" → "X" into each listed locale's TRANSLATIONS
# dict at import time, so compute_stats() counts them as translated and MT is
# never consulted for them.
COGNATES: dict[str, list[str]] = {
    # "Source" is a French/Dutch/German cognate (same spelling, same meaning).
    "Source": ["de", "fr", "nl"],
    # "Status:" — identical spelling in many Latin/Germanic-script locales.
    "Status:": ["de", "id", "nl", "pl", "pt"],
    # "{detail} in {sections}" — "in" is a preposition in German/Italian too;
    # no translatable words remain after placeholders.
    "{detail} in {sections}": ["de", "it"],
    # "baseline" is a common English loanword in Italian/Dutch software and
    # security jargon (e.g. "baseline di sicurezza"); both locale files
    # already keep "Drift"/"auth" untranslated in the same UI area.
    "baseline": ["it", "nl"],
    # "dev" = dev-dependency / dev channel tag; kept as the code-level token in
    # locales where MT returned it unchanged.
    "dev": ["id", "it", "ko", "nl", "pt", "ru", "sw", "tr", "vi"],
}

